code.js:
document.querySelectorAll('.ial__open').forEach(trigger => {
  const layer = trigger.nextElementSibling;
  const focusable = () => [...layer.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')];
  const open = () => { layer.hidden = false; focusable()[0].focus(); };
  const close = () => { layer.hidden = true; trigger.focus(); };
  trigger.addEventListener('click', open);
  layer.addEventListener('click', e => { if (e.target === layer || e.target.closest('button')) close(); });
  layer.addEventListener('keydown', e => {
    if (e.key === 'Escape') close();
    if (e.key === 'Tab') {
      const f = focusable(), first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  });
});
